export function fizzbuzz(count: number): string[] {
  const out: string[] = []
  for (let n = 1; n <= count; n++) {
    if (n % 15 === 0) out.push('FizzBuzz')
    else if (n % 3 === 0) out.push('Fizz')
    else if (n % 5 === 0) out.push('Buzz')
    else out.push(String(n))
  }
  return out
}
